sted", "generic_guidance_only", "no_local_recommendations", "other_when_explicitly_classified_valid"]}, "financial_reconciliation": {"note": "Financial PENDING does not by itself invalidate scientific data; ANOMALY blocks financial close and may pause new discretionary paid enrichment until reviewed.", "rules": {"provider_cost_event_coverage_target": 1.0, "unit_price_drift_critical_pct": 25, "unit_price_drift_warning_pct": 10, "wave_spend_critical_vs_versioned_forecast_pct": 25, "wave_spend_warning_vs_versioned_forecast_pct": 15}, "separate_from_data_acceptance": true, "states": ["COMPLETE", "PENDING", "ANOMALY"]}, "status_logic": {"COMPLETE": {"definition": "All hard integrity gates pass and completeness/processing thresholds meet the COMPLETE standard.", "precedence": 4}, "FAILED": {"definition": "No critical integrity violation, but collection/normalization completeness falls below minimum partial thresholds or job accounting cannot be reconciled.", "precedence": 2}, "PARTIAL": {"definition": "Integrity is intact and minimum thresholds are met, but COMPLETE thresholds are missed. Data may be analysis-eligible only where an Analysis Specification Contract explicitly accepts the missingness/comparability pattern.", "precedence": 3}, "QUARANTINED": {"definition": "Integrity, provenance, treatment, geometry, session, raw-evidence, or comparability trust is compromised. Retain data but exclude affected scope from analysis until remediated/reprocessed.", "precedence": 1, "wave_level_when": "A critical violation is systemic or cannot be safely isolated to a smaller scope."}}, "thresholds_qa_rules": {"cost_attribution_target": 0.999, "cost_unit_drift_critical": 0.5, "cost_unit_drift_error": 0.25, "cost_unit_drift_warning": 0.1, "partial_min_overall_terminal_coverage": 0.995, "partial_min_stratum_terminal_coverage": 0.95, "partial_min_surface_terminal_coverage": 0.99, "stratum_threshold_min_expected_jobs": 20}, "thresholds_wave": {"complete": {"critical_manifest_conformity_rate": 1.0, "job_accounting_rate": 1.0, "normalization_parity_rate_each_surface": 0.99, "normalization_parity_rate_overall": 0.995, "raw_payload_integrity_rate": 1.0, "required_enrichment_decision_coverage_rate": 0.99, "resolution_state_coverage_rate": 0.995, "valid_scientific_observation_rate_each_primary_surface": 0.99, "valid_scientific_observation_rate_overall": 0.995}, "partial_minimum": {"critical_manifest_conformity_rate": 1.0, "job_accounting_rate": 1.0, "normalization_parity_rate_each_surface": 0.97, "normalization_parity_rate_overall": 0.98, "raw_payload_integrity_rate": 1.0, "required_enrichment_decision_coverage_rate": 0.95, "resolution_state_coverage_rate": 0.97, "valid_scientific_observation_rate_each_primary_surface": 0.95, "valid_scientific_observation_rate_overall": 0.97}}}'::jsonb)
) as v(rule_code, scope, severity, description, rule_config)
cross join (select qa_contract_version_id from ops.qa_contract_version where contract_code = 'SED_WAVE_QA' and version_code = '0.1') cv(qa_contract_version_id)
on conflict (qa_contract_version_id, rule_code) do update set
  scope = excluded.scope, severity = excluded.severity,
  description = excluded.description, rule_config = excluded.rule_config;

